                    and
                    (self.mailfrom == other.mailfrom)
                    and
                    (self.mailto == other.mailto)
                    and
                    (self.subject == other.subject)
                    and
                    (self.server == other.server)
                    and
                    (self.port == other.port)
                    and
                    (self.tls == other.tls)
                    and
