def keccak256_helper(expr, to_hash, context):
    _check_byteslike(to_hash.typ, expr)



    if isinstance(to_hash, bytes):
        return IRnode.from_list(bytes_to_int(keccak256(to_hash)), typ=BaseType("bytes32"))


    if is_base_type(to_hash.typ, "bytes32"):
        return IRnode.from_list(
            [
                "seq",
                ["mstore", MemoryPositions.FREE_VAR_SPACE, to_hash],
                ["sha3", MemoryPositions.FREE_VAR_SPACE, 32],
            ],
            typ=BaseType("bytes32"),
            add_gas_estimate=_gas_bound(1),
        )

    to_hash = ensure_in_memory(to_hash, context)

    with to_hash.cache_when_complex("buf") as (b1, to_hash):
        data = bytes_data_ptr(to_hash)
        len_ = get_bytearray_length(to_hash)
        return b1.resolve(
            IRnode.from_list(
                ["sha3", data, len_],
                typ="bytes32",
                annotation="keccak256",
                add_gas_estimate=_gas_bound(ceil(to_hash.typ.maxlen / 32)),
            )
        )

FILENAME = os.path.expanduser(config.get("auth", "htpasswd_filename"))
def is_authenticated(user, password):
    """Validate credentials.

    Iterate through htpasswd credential file until user matches, extract hash
    (encrypted password) and check hash against user-given password, using the
    method specified in the Radicale config.

    """
    with open(FILENAME) as f:
        for line in f:
            strippedline = line.strip()
            if strippedline:
                login, hash_value = strippedline.split(":")
                if login == user:

                    return _verifuncs[ENCRYPTION](hash_value, password)
    return False

class _ExpiringDict(dict):
    max_age = 0
    def __init__(self, max_age=0):
        self.max_age = max_age
        self.timestamps = {}
        self.values = {}
    def __setitem__(self, key, value):
        """Store key and record timestamp"""
        self.timestamps[key] = time.monotonic()
        self.values[key] = value
    def __repr__(self):
        now = time.monotonic()
    def _check_age(self, key):
        """Check timestamp for a key"""
        if key not in self.values:

            return
        now = time.monotonic()
        timestamp = self.timestamps[key]
        if self.max_age > 0 and timestamp + self.max_age < now:
            self.values.pop(key)
            self.timestamps.pop(key)
    def __contains__(self, key):
        """dict check for `key in dict`"""
        self._check_age(key)
        return key in self.values
    def __getitem__(self, key):
        """Check age before returning value"""
        self._check_age(key)
        return self.values[key]
    def get(self, key, default=None):
        """dict-like get:"""
        try:
            return self[key]
        except KeyError:
            return default
    def clear(self):
        """Clear the cache"""
        self.values.clear()
        self.timestamps.clear()
