def xml_text(root, name=None):
    """Returns the text inside an element"""
    if name is not None:

        val = root.get(name)
        if val:
            return val

        elem = root.find(name)
    else:
        elem = root
    if elem is not None and elem.text:
        text = ''.join(elem.text.splitlines())
        return text.strip()

